const CAMPAIGN_NAME_COLLATOR = new Intl.Collator("ko-KR", {
  numeric: true,
  sensitivity: "base"
});
function placeCampaignAfter(campaigns, campaignId, afterId) {
  const targetIndex = campaigns.findIndex((campaign) => campaign?.id === campaignId);
  const afterIndex = campaigns.findIndex((campaign) => campaign?.id === afterId);
  if (targetIndex < 0 || afterIndex < 0 || targetIndex === afterIndex + 1) return campaigns;
  const [target] = campaigns.splice(targetIndex, 1);
  const resolvedAfterIndex = campaigns.findIndex((campaign) => campaign?.id === afterId);
  campaigns.splice(resolvedAfterIndex + 1, 0, target);
  return campaigns;
}
function applyCampaignSortExceptions(campaigns) {
  return placeCampaignAfter(campaigns, "major-piece-campaign", "knight-journey");
}
function sortCampaignsByKoreanName(campaigns) {
  const sorted = [...campaigns].sort((a, b) => {
    const byName = CAMPAIGN_NAME_COLLATOR.compare(a?.name || "", b?.name || "");
    return byName || String(a?.id || "").localeCompare(String(b?.id || ""));
  });
  return applyCampaignSortExceptions(sorted);
}
