CARD_DEFS.forEach((card2) => {
  Object.assign(card2, internalBalanceCard(card2));
  if (PIECE_CREATION_TEXT[card2.id]) card2.text = PIECE_CREATION_TEXT[card2.id];
  if (card2.id === "checker") card2.stars = 2.5;
  const update = SEPTEMBER18_CARD_UPDATES[card2.id];
  if (update?.name) card2.name = update.name;
  if (update?.description) card2.text = update.description;
  if (card2.id === "reversal") card2.text = card2.text.replace("이번 턴 아군", "이번 턴에 아군");
  if (update?.ratingHalfStars !== void 0) card2.stars = update.ratingHalfStars / 2;
  if (update?.draftCategory) {
    for (const ids of Object.values(CARD_CATEGORY_GROUPS)) {
      const index = ids.indexOf(card2.id);
      if (index >= 0) ids.splice(index, 1);
    }
    card2.phase = update.draftCategory;
    CARD_CATEGORY_BY_ID[card2.id] = card2.phase;
    CARD_CATEGORY_GROUPS[card2.phase].push(card2.id);
  }
  if (["campfire", "reversal"].includes(card2.id)) card2.target = "own-minor";
  if (card2.id === "scarecrow") card2.target = "own-piece";
  if (card2.id === "othello") delete card2.target;
  const october = OCTOBER7_CARD_UPDATES[card2.id];
  if (october) {
    card2.text = october.description;
    if (october.ratingHalfStars) card2.stars = october.ratingHalfStars / 2;
    if (october.art) card2.art = october.art;
  }
  if (DURATION_CARD_DISPLAY_TEXT[card2.id]) card2.text = DURATION_CARD_DISPLAY_TEXT[card2.id];
  if (card2.id === "chimera") card2.target = "own-major";
  if (card2.id === "initiative") card2.text = card2.text.replace("10수", "8수");
  if (card2.id === "majesty") card2.rarity = "epic";
  if ((CARD_CATEGORY_BY_ID[card2.id] || card2.phase) === "RULE") card2.stars = null;
});
