for (const card2 of CARD_DEFS) {
  const update = REFORM_CARD_UPDATES[card2.id];
  if (update) {
    if (update.description) card2.text = cardPresentationText({ id: card2.id, text: update.description });
    if (update.rarity) card2.rarity = update.rarity;
    if (update.draftCategory) {
      for (const ids of Object.values(CARD_CATEGORY_GROUPS)) {
        const i = ids.indexOf(card2.id);
        if (i >= 0) ids.splice(i, 1);
      }
      card2.phase = update.draftCategory;
      CARD_CATEGORY_BY_ID[card2.id] = card2.phase;
      CARD_CATEGORY_GROUPS[card2.phase].push(card2.id);
    }
  }
  if (OCTOBER13_CARDS.some((c) => c.id === card2.id && c.rarity === "common")) card2.stars = 2.5;
  if (card2.id === "horse-riding") {
    card2.text = TEMPORARY_HORSE_RIDING_CARD_UPDATE.description;
    card2.passive = false;
    card2.autoPlay = false;
    delete card2.target;
    for (const ids of Object.values(CARD_CATEGORY_GROUPS)) {
      const i = ids.indexOf(card2.id);
      if (i >= 0) ids.splice(i, 1);
    }
    card2.phase = TEMPORARY_HORSE_RIDING_CARD_UPDATE.draftCategory;
    CARD_CATEGORY_BY_ID[card2.id] = card2.phase;
    CARD_CATEGORY_GROUPS[card2.phase].push(card2.id);
  }
}
PASSIVE_CARD_IDS.delete("horse-riding");
for (const card2 of CARD_DEFS) {
  if (card2.id === "loyalist") {
    for (const ids of Object.values(CARD_CATEGORY_GROUPS)) {
      const i = ids.indexOf(card2.id);
      if (i >= 0) ids.splice(i, 1);
    }
    card2.phase = "MIDDLE";
    CARD_CATEGORY_BY_ID[card2.id] = "MIDDLE";
    CARD_CATEGORY_GROUPS.MIDDLE.push(card2.id);
  }
  if (card2.id === "summon-colossus") {
    card2.passive = true;
    card2.autoPlay = false;
    card2.text = COLOSSUS_CORE_CARD_UPDATE.description;
    PASSIVE_CARD_IDS.add(card2.id);
  }
  if (OPENING_CONVERTED_PASSIVE_IDS.includes(card2.id) || card2.id === "shotgun-king") {
    card2.passive = true;
    card2.autoPlay = false;
    delete card2.target;
    PASSIVE_CARD_IDS.add(card2.id);
    if (OPENING_PASSIVE_DESCRIPTIONS[card2.id]) card2.text = OPENING_PASSIVE_DESCRIPTIONS[card2.id];
  }
}
for (const card2 of CARD_DEFS) {
  const update = OCTOBER14_CARD_UPDATES[card2.id];
  if (!update) continue;
  if (update.description) card2.text = update.description;
  if (update.ratingHalfStars !== void 0) card2.stars = update.ratingHalfStars / 2;
  if (update.rarity) card2.rarity = update.rarity;
}
for (const card2 of CARD_DEFS) {
  const update = OCTOBER27_CARD_UPDATES[card2.id];
  if (!update) continue;
  if (update.name) card2.name = update.name;
  if (update.art) {
    card2.art = update.art;
    card2.imageId = update.art;
  }
  if (update.description) card2.text = update.description;
  if (update.draftCategory) {
    for (const ids of Object.values(CARD_CATEGORY_GROUPS)) {
      const index = ids.indexOf(card2.id);
      if (index >= 0) ids.splice(index, 1);
    }
    card2.phase = update.draftCategory;
    CARD_CATEGORY_BY_ID[card2.id] = card2.phase;
    CARD_CATEGORY_GROUPS[card2.phase].push(card2.id);
  }
  if (update.rarity) card2.rarity = update.rarity;
  if (update.activation === "PASSIVE") {
    card2.passive = true;
    card2.autoPlay = false;
    delete card2.target;
    PASSIVE_CARD_IDS.add(card2.id);
  }
  if (["octopus", "transmission-tower", "siege-ram"].includes(card2.id)) card2.target = "own-minor";
  if (card2.id === "death-squad") card2.target = "own-pawn";
  if (card2.id === "clockwork") {
    card2.target = "own-rook";
  }
}
for (const card2 of CARD_DEFS) {
  const update = NOVEMBER_CARD_UPDATES[card2.id];
  if (update) {
    if (update.description) card2.text = update.description;
    if (update.rarity) card2.rarity = update.rarity;
    if (update.name) card2.name = update.name;
    if (update.enabled === true) {
      card2.disabled = false;
      card2.enabled = true;
    }
  }
  if (card2.id === "omega-chesstron") {
    card2.helpItems = [{ icons: ["omegaChesstron"], text: OMEGA_HELP }, { icons: [], text: DIRECT_ACQUISITION_ONLY_CARD_HELP }];
    card2.help = card2.helpItems.map((x) => x.text).join(" ");
  }
  if (card2.id === "summon-colossus") {
    card2.helpItems = [{ icons: ["colossus"], text: MEGA_CORE_HELP }, { icons: ["core"], text: COLOSSUS_CORE_OBJECT_HELP }, { icons: [], text: DIRECT_ACQUISITION_ONLY_CARD_HELP }];
    card2.help = card2.helpItems.map((x) => x.text).join(" ");
  }
}
