function createAiColorChoice(options = {}) {
  const campaign = options.campaign === true;
  const activeColor = campaign ? campaignPlayerColor : humanControlledColor();
  const choice = document.createElement("div");
  choice.className = campaign ? "ai-color-choice campaign-ai-color-choice" : "ai-color-choice";
  choice.setAttribute("role", "group");
  choice.setAttribute("aria-label", "AI 대국 색 선택");
  ["white", "black"].forEach((color2) => {
    const button = document.createElement("button");
    const selected2 = activeColor === color2;
    button.type = "button";
    button.className = ["ai-color-button", selected2 ? "selected" : ""].filter(Boolean).join(" ");
    button.dataset.aiColor = color2;
    button.textContent = color2 === "white" ? "WHITE" : "BLACK";
    button.setAttribute("aria-pressed", selected2 ? "true" : "false");
    button.addEventListener("click", () => {
      if (campaign) chooseCampaignAiHumanColor(color2);
      else chooseAiHumanColor(color2);
    });
    choice.append(button);
  });
  return choice;
}
