  const spaceLeft = rect.left - padding - gap;
  if (preferredHorizontalDirection === "right" && spaceRight >= helpWidth) {
    return {
      x: rect.right + gap,
      y: clamp2(rect.top + (rect.height - helpHeight) / 2, minY, maxY),
      direction: "right"
    };
  }
  if (spaceRight >= helpWidth || spaceLeft >= helpWidth) {
    const openLeft = spaceLeft >= helpWidth && spaceLeft > spaceRight;
    return {
      x: openLeft ? rect.left - gap - helpWidth : rect.right + gap,
      y: clamp2(rect.top + (rect.height - helpHeight) / 2, minY, maxY),
      direction: openLeft ? "left" : "right"
    };
  }
  const aboveY = rect.top - gap - helpHeight;
  if (aboveY >= minY) return { x: centeredX, y: aboveY, direction: "above" };
  const belowY = rect.bottom + gap;
  if (belowY + helpHeight <= viewportHeight - padding) return { x: centeredX, y: belowY, direction: "below" };
