  if (campaignCardBanIds === null) return;
  if (!onlineCampaign && !betaFriendlyRoomActive && [BLACK_TOWER_CAMPAIGN_ID, MAJOR_PIECE_CONFIGURATION.campaignId].includes(campaign.id)) return startCanonicalV19CampaignGame(campaign, playerColor, campaignCardBanIds);
  if (!onlineCampaign && !betaFriendlyRoomActive && canonicalCampaignSupported(campaign.id)) return startCanonicalCampaignGame(campaign, playerColor, campaignCardBanIds);
  if (!ruleConfigCampaign) playSound("getCard", "white");
  if (cardEl) animateCard(cardEl, "draft");
  clearTutorialState();
  campaignPanelOpen = false;
  selectedSpecialCampaignId = null;
  playMode = "campaign";
  const enemyColor = opponent(playerColor);
  const displayGoal = campaignDisplayGoal(campaign, playerColor);
  localPlayMode = campaignPlayMode === "single" ? "single" : "offline";
  aiHumanColor = playerColor;
  resetGame(false, campaignCardBanIds);
  if (onlineCampaign && online.enabled) online.eventNonce = 0;
  state.campaign = {
    id: campaign.id,
    name: campaign.name,
    setup: campaign.setup,
    goal: displayGoal,
    playerColor,
    enemyColor,
    reviewEnded: false
  };
  rememberCampaignSelection(state.campaign);
  state.board = consumeCampaignPreviewBoard(campaign, playerColor);
  state.localMode = localPlayMode;
  state.aiHumanColor = aiHumanColor;
  state.madAi = createMadAiState(false);
  enableOfflineCampaignBoardFlipDefault();
  const auctionCampaign = campaign.setup === "auctionChess";
  const shotgunCampaign = campaign.setup === "shotgunKing";
  const blackTowerCampaign = campaign.setup === "blackTower";
