  const bloodMoonCampaign = campaign.setup === "bloodMoon";
  const wideBoardCampaign = campaign.setup === "wideBoard";
  const fogWarCampaign = campaign.setup === "fogWar";
  const factoryCampaign = campaign.setup === "conveyorFactory";
  const configurableDraftCampaign = wideBoardCampaign || fogWarCampaign || factoryCampaign;
