els.auctionBody?.addEventListener("click", (event2) => {
  const bidButton = event2.target.closest("[data-auction-bid]");
  if (bidButton) {
    bidAuction(bidButton.dataset.auctionBid);
    return;
  }
  const reserveButton = event2.target?.closest?.("[data-auction-reserve-color]");
  if (reserveButton) {
    selectAuctionReserve(reserveButton.dataset.auctionReserveColor, Number(reserveButton.dataset.auctionReserveIndex));
    return;
  }
  if (event2.target.closest("[data-auction-finish]")) {
    finishAuctionPlacement();
  }
});
els.auctionBody?.addEventListener("dragstart", (event2) => {
  const reserveButton = event2.target?.closest?.("[data-auction-reserve-color]");
  if (!reserveButton) return;
  const color2 = reserveButton.dataset.auctionReserveColor;
  const index = Number(reserveButton.dataset.auctionReserveIndex);
  const auction = currentAuction();
  if (!auction || state.mode !== "auction-placement" || !canControlAuctionColor(color2)) return;
  if (color2 !== auction.placementColor) return;
  auction.selectedPlacement = { color: color2, index };
  event2.dataTransfer.effectAllowed = "copy";
  event2.dataTransfer.setData("text/plain", `auction:${color2}:${index}`);
});
