els.draftDeleteToggle?.addEventListener("click", () => {
  if (betaFriendlyRoomActive) {
    if (!supportsDraftDeleteSetting(betaFriendlyRoomView.configuration?.mode, betaFriendlyRoomView.configuration?.campaignId)) {
      toast("이 모드에서는 드래프트 삭제를 변경할 수 없습니다.");
      renderSettingsState();
      return;
    }
    if (!canChangeBetaFriendlyDraftDelete()) {
      toast("게임 시작 전 방장만 드래프트 삭제를 변경할 수 있습니다.");
      renderSettingsState();
      return;
    }
    const next = !draftDeleteEnabled;
    draftDeleteEnabled = next;
    if (state) state.draftDelete = next;
    queueBetaFriendlySetupCommit({ game: true });
    renderSettingsState();
    return;
  }
  if (playMode === "multiplayer" || online.enabled && playMode !== "online") {
    toast("멀티플레이에서는 드래프트 삭제를 사용할 수 없습니다.");
    renderSettingsState();
    return;
  }
  if (online.enabled && !online.isHost) {
    toast("친선전에서는 방장의 드래프트 삭제 설정을 따릅니다.");
    renderSettingsState();
    return;
  }
  if (!canChangeGameSetupOptions()) {
    toast("게임이 진행 중일 때는 변경할 수 없습니다.");
    renderSettingsState();
    return;
  }
  draftDeleteEnabled = !draftDeleteEnabled;
  if (state) state.draftDelete = draftDeleteEnabled;
  if (online.enabled && online.isHost) queueOnlineStateSave();
  renderAll();
});
